import sys

def main():
    import sys
    input = sys.stdin.read().splitlines()
    t = int(input[0])
    results = []
    for i in range(1, t + 1):
        s, p = input[i].split()
        if len(p) != 2 * len(s):
            results.append("Impossible")
        else:
            found = False
            for j in range(len(p) - len(s) + 1):
                if p[j:j+len(s)] == s and p[:j] + p[j+len(s):] == s:
                    found = True
                    break
            results.append("Possible" if found else "Impossible")
    print("\n".join(results))

if __name__ == "__main__":
    main()
